function initNewsletter() {
  const form = document.getElementById("newsletterForm");
  if (!form) return;

  const status = document.getElementById("newsletterStatus");
  const email = form.querySelector("input[name='email']");
  const emailErr = document.querySelector("[data-error-for='email']");

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    if (!email) return;

    const value = email.value.trim();
    const ok = validateEmail(value);
    if (emailErr) emailErr.textContent = ok ? "" : "Please enter a valid email.";
    if (!ok) return;

    form.querySelector("button[type='submit']")?.setAttribute("disabled", "disabled");
    if (status) status.textContent = "Subscribed (frontend demo). Backend will store this in Phase 2.";

    await new Promise((r) => setTimeout(r, 500));
    form.reset();
    form.querySelector("button[type='submit']")?.removeAttribute("disabled");
