}

async function render() {
  const id = getId();
  const root = document.getElementById("newsArticle");
  if (!root) return;

  const news = await safeJson("data/news.json");
  const item = news.find((n) => n.id === id) || news[0];

  if (!item) {
    root.innerHTML = `
