import { validateEmail } from "./form-validation.js";

function setErr(name, msg) {
  const el = document.querySelector(`[data-error-for='${CSS.escape(name)}']`);
  if (el) el.textContent = msg || "";
}

function getValue(form, name) {
  const el = form.elements.namedItem(name);
  return el && "value" in el ? String(el.value).trim() : "";
}

function getApiBase() {
  const m = document.querySelector('meta[name="kdu-api-base"]');
  const v = m?.getAttribute("content")?.trim();
  return v || "";
}

function validate(form) {
  const name = getValue(form, "name");
  const email = getValue(form, "email");
  const message = getValue(form, "message");

  let ok = true;
  setErr("name", "");
  setErr("email", "");
  setErr("message", "");

  if (name.length < 2) {
    setErr("name", "Please enter your name.");
    ok = false;
  }
  if (!validateEmail(email)) {
    setErr("email", "Please enter a valid email.");
    ok = false;
  }
  if (message.length < 10) {
    setErr("message", "Please write a short message (10+ characters).");
    ok = false;
  }

  return ok;
}

function boot() {
  const form = document.getElementById("contactForm");
  const status = document.getElementById("contactStatus");
  if (!form) return;

  const apiBase = getApiBase();

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    if (!validate(form)) return;

    const btn = form.querySelector("button[type='submit']");
    btn?.setAttribute("disabled", "disabled");
    if (status) status.textContent = apiBase ? "Sending…" : "Set kdu-api-base in the page head to enable sending.";

    if (!apiBase) {
      btn?.removeAttribute("disabled");
      return;
    }

    try {
      const url = `${apiBase.replace(/\/+$/, "")}/api/contact.php`;
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({
          name: getValue(form, "name"),
          email: getValue(form, "email"),
          message: getValue(form, "message"),
        }),
      });
      const raw = await res.text();
      let data = {};
      try {
        data = raw ? JSON.parse(raw) : {};
      } catch {
        data = {};
      }

      if (!res.ok) {
        const errs = data.errors || {};
        if (errs.name) setErr("name", errs.name);
        if (errs.email) setErr("email", errs.email);
        if (errs.message) setErr("message", errs.message);
        const msg =
          errs.name || errs.email || errs.message || data.error || (raw && raw.length < 220 ? raw : "") || `Request failed (${res.status})`;
        if (status) status.textContent = typeof msg === "string" ? msg : "Something went wrong.";
      } else if (status) {
        status.textContent = data.message || "Thanks — we received your message.";
        form.reset();
        setErr("name", "");
        setErr("email", "");
        setErr("message", "");
      }
    } catch (err) {
      console.error("Contact submit failed:", err);
      if (status) {
        status.textContent =
          err && err.message
            ? `${err.message}. Check kdu-api-base URL and that the API is running.`
            : "Could not reach the server. Check kdu-api-base and your network.";
      }
    } finally {
      btn?.removeAttribute("disabled");
    }
  });
}

boot();

/**
 * API base URL for newsletter, contact, etc.
 *
 * - On localhost / 127.0.0.1: uses XAMPP by default (`Kdu_backend/public`) so Live Server works
 *   without a working Railway URL. Override with <meta name="kdu-api-base-local" content="...">.
 * - On production (Vercel, etc.): uses <meta name="kdu-api-base" content="https://your-api...">.
 * - To force a remote API while on localhost, set kdu-api-base to a real URL other than the
 *   default placeholder below.
 */
const RAILWAY_PLACEHOLDER = /^https?:\/\/kdu-backend-production\.up\.railway\.app\/?$/i;
const LOCAL_DEFAULT = "http://127.0.0.1/Kdu_backend/public";

function trimSlash(s) {
  return String(s || "").replace(/\/+$/, "");
}

export function getKduApiBase() {
  const host = window.location.hostname;
  const isLocal = host === "localhost" || host === "127.0.0.1" || host === "[::1]";

  const localMeta = document.querySelector('meta[name="kdu-api-base-local"]')?.getAttribute("content")?.trim();
  const metaRaw = document.querySelector('meta[name="kdu-api-base"]')?.getAttribute("content")?.trim() ?? "";

  if (isLocal) {
    const localBase = trimSlash(localMeta || LOCAL_DEFAULT);
    const remote = trimSlash(metaRaw);
    const useXampp = !metaRaw || RAILWAY_PLACEHOLDER.test(remote);
    return useXampp ? localBase : remote;
  }

  return trimSlash(metaRaw);
}

